mkdir -p src
cat <<'RS' > src/main.rs
use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{self, IsTerminal};
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};

const VERSION: &str = "0.2.18";
const DEFAULT_DEPTH_WITH_FLAG: usize = 1;
const DEFAULT_AGGR: u64 = 1024 * 1024; // 1M
const BAR_WIDTH: usize = 32;
const MAX_DEPTH_CAP: usize = 8; // observed cap
const NAME_MAX_BASE: usize = 25;

#[derive(Debug)]
struct Config {
    depth: usize, // max depth to display, capped
    aggr_threshold: u64, // 0 means no aggr
    usage: bool,
    bytes: bool,
    files_only: bool,
    exclude: Vec<String>,
    no_hidden: bool,
    ascii: bool,
}

#[derive(Debug, Clone)]
struct Node {
    name: String, // basename or <collection> etc
    path: PathBuf, // actual path for file, or empty for collection
    size: u64, // total size (including children)
    own_size: u64, // own size (dir entry or file size)
    is_dir: bool,
    is_symlink: bool,
    children: Vec<Node>,
    // for aggregated node
    is_aggregated: bool,
}

fn human_size(size: u64) -> String {
    if size < 1024 {
        format!("{} B", size)
    } else if size < 1024 * 1024 {
        format!("{:.2} KiB", size as f64 / 1024.0)
    } else if size < 1024 * 1024 * 1024 {
        format!("{:.2} MiB", size as f64 / (1024.0 * 1024.0))
    } else if size < 1024u64 * 1024 * 1024 * 1024 {
        format!("{:.2} GiB", size as f64 / (1024.0 * 1024.0 * 1024.0))
    } else {
        format!("{:.2} TiB", size as f64 / (1024.0 * 1024.0 * 1024.0 * 1024.0))
    }
}

fn parse_depth(s: &str) -> Option<usize> {
    // try parse as usize integer
    // s may be like "2", "0", etc. Return None if fails.
    if s.is_empty() {
        return None;
    }
    // For depth, we only allow digits, no suffix
    // But original allows e.g., "2"? Only integer.
    match s.parse::<usize>() {
        Ok(v) => Some(v),
        Err(_) => None,
    }
}

fn parse_aggr(s: &str) -> Option<u64> {
    // s like "1K", "10M", "1024", "1B", "0", etc.
    // Valid: number + optional K/M/G (case-insensitive) OR number + B (bytes) OR plain number
    // Invalid if K/M/G followed by B, or other suffixes
    if s.is_empty() {
        return None;
    }
    // Find where digits end
    let mut num_end = 0;
    for (i, ch) in s.char_indices() {
        if ch.is_ascii_digit() {
            num_end = i + ch.len_utf8();
        } else {
            break;
        }
    }
    if num_end == 0 {
        return None;
    }
    let num_str = &s[..num_end];
    let suffix = &s[num_end..];
    let num: u64 = match num_str.parse() {
        Ok(v) => v,
        Err(_) => return None,
    };
    if suffix.is_empty() {
        return Some(num);
    }
    // suffix can be "B" or "K" or "M" or "G" case-insensitive, but not "KB" etc.
    // So suffix length 1, and must be B,K,M,G
    if suffix.len() == 1 {
        match suffix.to_ascii_uppercase().as_str() {
            "B" => Some(num),
            "K" => Some(num * 1024),
            "M" => Some(num * 1024 * 1024),
            "G" => Some(num * 1024 * 1024 * 1024),
            _ => None,
        }
    } else {
        None
    }
}

fn print_help() {
    println!("Usage: ./executable [options] <path> [<path>..]");
    println!();
    println!("Options:");
    println!("    -d, --depth [DEPTH] show directories up to depth N (def 1)");
    println!("    -a, --aggr [N[KMG]] aggregate smaller than N B/KiB/MiB/GiB (def 1M)");
    println!("    -s, --summary       equivalent to -da, or -d1 -a1M");
    println!("    -u, --usage         report real disk usage instead of file size");
    println!("    -b, --bytes         print sizes in bytes");
    println!("    -f, --files-only    skip directories for a fast local overview");
    println!("    -x, --exclude NAME  exclude matching files or directories");
    println!("    -H, --no-hidden     exclude hidden files");
    println!("    -A, --ascii         ASCII characters only, no colors");
    println!("    -h, --help          show help");
    println!("    -v, --version       print version number");
}

fn print_version() {
    println!("dutree version {}", VERSION);
}

fn main() {
    let args: Vec<String> = env::args().collect();
    // Config defaults
    let mut depth_opt: Option<usize> = None; // None = unlimited (will be capped to MAX_DEPTH_CAP)
    let mut aggr_opt: Option<u64> = None; // None = no aggr
    let mut usage = false;
    let mut bytes = false;
    let mut files_only = false;
    let mut exclude: Vec<String> = Vec::new();
    let mut no_hidden = false;
    let mut ascii = false;
    let mut summary = false;
    let mut help = false;
    let mut version = false;

    let mut paths: Vec<String> = Vec::new();

    let mut i = 1;
    while i < args.len() {
        let token = &args[i];
        if token == "--" {
            // remaining are paths
            i += 1;
            while i < args.len() {
                paths.push(args[i].clone());
                i += 1;
            }
            break;
        }
        if token.starts_with("--") {
            // long option
            if token == "--help" {
                help = true;
                i += 1;
                continue;
            } else if token == "--version" {
                version = true;
                i += 1;
                continue;
            } else if token == "--bytes" {
                bytes = true;
                i += 1;
                continue;
            } else if token == "--usage" {
                usage = true;
                i += 1;
                continue;
            } else if token == "--files-only" {
                files_only = true;
                i += 1;
                continue;
            } else if token == "--no-hidden" {
                no_hidden = true;
                i += 1;
                continue;
            } else if token == "--ascii" {
                ascii = true;
                i += 1;
                continue;
            } else if token == "--summary" {
                summary = true;
                i += 1;
                continue;
            } else if token.starts_with("--depth") {
                // --depth or --depth=...
                if token == "--depth" {
                    // default depth 1, does not consume next token
                    depth_opt = Some(DEFAULT_DEPTH_WITH_FLAG);
                    i += 1;
                    continue;
                } else if token.starts_with("--depth=") {
                    let val_str = &token["--depth=".len()..];
                    if let Some(d) = parse_depth(val_str) {
                        depth_opt = Some(d);
                    } else {
                        // fallback to default 1 (as observed for --depth=foo)
                        depth_opt = Some(DEFAULT_DEPTH_WITH_FLAG);
                    }
                    i += 1;
                    continue;
                } else {
                    // unrecognized, like --depth2? but we should treat as unknown?
                    // For simplicity, if it starts with --depth but not exact, treat as unknown?
                    // Check if token is like --depth=... already handled, else unknown
                    eprintln!("Unrecognized option: '{}'", token.trim_start_matches("--"));
                    print_help();
                    std::process::exit(1);
                }
            } else if token.starts_with("--aggr") {
                // --aggr or --aggr=...
                // Accept --aggr and --aggregate? We'll support both
                let is_aggr = token == "--aggr" || token == "--aggregate";
                if is_aggr {
                    aggr_opt = Some(DEFAULT_AGGR);
                    i += 1;
                    continue;
                } else if token.starts_with("--aggr=") || token.starts_with("--aggregate=") {
                    let val_str = if token.starts_with("--aggr=") {
                        &token["--aggr=".len()..]
                    } else {
                        &token["--aggregate=".len()..]
                    };
                    if let Some(sz) = parse_aggr(val_str) {
                        aggr_opt = Some(sz);
                    } else {
                        eprintln!("invalid argument '{}'", val_str);
                        std::process::exit(1);
                    }
                    i += 1;
                    continue;
                } else {
                    // For long aggr, if token is like --aggr1K? Not valid, treat as unknown? But observed --aggr 1K is treated as path, not as option with value. So --aggr1K would be unknown?
                    // We'll treat any token starting with --aggr but not exact as unknown if it doesn't contain =
                    eprintln!("Unrecognized option: '{}'", token.trim_start_matches("--"));
                    print_help();
                    std::process::exit(1);
                }
            } else if token.starts_with("--exclude") {
                if token == "--exclude" {
                    // need next token as arg
                    i += 1;
                    if i >= args.len() {
                        print_help();
                        eprintln!("Argument to option 'exclude' missing");
                        std::process::exit(1);
                    }
                    let val = args[i].clone();
                    exclude.push(val);
                    i += 1;
                    continue;
                } else if token.starts_with("--exclude=") {
                    let val_str = &token["--exclude=".len()..];
                    exclude.push(val_str.to_string());
                    i += 1;
                    continue;
                } else {
                    eprintln!("Unrecognized option: '{}'", token.trim_start_matches("--"));
                    print_help();
                    std::process::exit(1);
                }
            } else {
                // unknown long option
                let name = token.trim_start_matches("--");
                // split at '=' for error message? For --unknown, name is "unknown"
                let opt_name = if let Some(eq_pos) = name.find('=') {
                    &name[..eq_pos]
                } else {
                    name
                };
                eprintln!("Unrecognized option: '{}'", opt_name);
                print_help();
                std::process::exit(1);
            }
        } else if token.starts_with("-") && token.len() > 1 {
            // short options cluster
            let chars: Vec<char> = token[1..].chars().collect();
            let mut j = 0;
            while j < chars.len() {
                let c = chars[j];
                match c {
                    'b' => { bytes = true; j+=1; },
                    'u' => { usage = true; j+=1; },
                    'f' => { files_only = true; j+=1; },
                    'H' => { no_hidden = true; j+=1; },
                    'A' => { ascii = true; j+=1; },
                    's' => { summary = true; j+=1; },
                    'h' => { help = true; j+=1; },
                    'v' => { version = true; j+=1; },
                    'd' => {
                        // depth
                        let remaining: String = chars[j+1..].iter().collect();
                        if !remaining.is_empty() {
                            // attached arg
                            // For -d, remaining could include '='? e.g., -d=2 remaining "=2"
                            // Try parse remaining
                            if let Some(d) = parse_depth(&remaining) {
                                depth_opt = Some(d);
                            } else {
                                // fallback depth 1, consume remaining as invalid depth
                                depth_opt = Some(DEFAULT_DEPTH_WITH_FLAG);
                            }
                            // break cluster, remaining consumed
                            break;
                        } else {
                            // no attached, look ahead next token
                            if i+1 < args.len() && !args[i+1].starts_with("-") {
                                let next = args[i+1].clone();
                                // try parse
                                if let Some(d) = parse_depth(&next) {
                                    depth_opt = Some(d);
                                } else {
                                    // fallback depth 1, but still consume next token as attempted depth
                                    depth_opt = Some(DEFAULT_DEPTH_WITH_FLAG);
                                }
                                // consume next token
                                i+=1;
                            } else {
                                // no next token or next is option, default depth 1
                                depth_opt = Some(DEFAULT_DEPTH_WITH_FLAG);
                            }
                            break;
                        }
                    },
                    'a' => {
                        // aggr
                        let remaining: String = chars[j+1..].iter().collect();
                        if !remaining.is_empty() {
                            // attached
                            if let Some(sz) = parse_aggr(&remaining) {
                                aggr_opt = Some(sz);
                            } else {
                                eprintln!("invalid argument '{}'", remaining);
                                std::process::exit(1);
                            }
                            break;
                        } else {
                            // look ahead
                            if i+1 < args.len() && !args[i+1].starts_with("-") {
                                let next = args[i+1].clone();
                                if let Some(sz) = parse_aggr(&next) {
                                    aggr_opt = Some(sz);
                                    i+=1;
                                } else {
                                    eprintln!("invalid argument '{}'", next);
                                    std::process::exit(1);
                                }
                            } else {
                                // default
                                aggr_opt = Some(DEFAULT_AGGR);
                            }
                            break;
                        }
                    },
                    'x' => {
                        let remaining: String = chars[j+1..].iter().collect();
                        if !remaining.is_empty() {
                            exclude.push(remaining);
                            break;
                        } else {
                            // need next token
                            if i+1 >= args.len() {
                                print_help();
                                eprintln!("Argument to option 'x' missing");
                                std::process::exit(1);
                            }
                            let next = args[i+1].clone();
                            // For -x, even if next starts with '-', we take it as pattern? Earlier we observed --exclude -b takes -b as pattern. For short -x -b, what happens? -x -b: -x pattern "-b" -> no exclude, but -b flag would be consumed as pattern, not as flag. So for -x, we should take next token regardless of starting with '-'.
                            exclude.push(next);
                            i+=1;
                            break;
                        }
                    },
                    _ => {
                        // unrecognized short option
                        eprintln!("Unrecognized option: '{}'", c);
                        print_help();
                        std::process::exit(1);
                    }
                }
            }
            i+=1;
            continue;
        } else {
            // path
            paths.push(token.clone());
            i+=1;
        }
    }

    if help {
        print_help();
        std::process::exit(0);
    }
    if version {
        print_version();
        std::process::exit(0);
    }

    // summary overrides depth and aggr
    if summary {
        depth_opt = Some(1);
        aggr_opt = Some(DEFAULT_AGGR);
    }

    let depth = match depth_opt {
        Some(d) => std::cmp::min(d, MAX_DEPTH_CAP),
        None => MAX_DEPTH_CAP, // unlimited capped to MAX_DEPTH_CAP to match observed
    };

    let aggr_threshold = aggr_opt.unwrap_or(0);

    if paths.is_empty() {
        paths.push(".".to_string());
    }

    // Check existence of paths, if any does not exist, print error to stderr and exit 1
    for p in &paths {
        if fs::symlink_metadata(p).is_err() {
            eprintln!("path {} doesn't exist", p);
            std::process::exit(1);
        }
    }

    let config = Config {
        depth,
        aggr_threshold,
        usage,
        bytes,
        files_only,
        exclude,
        no_hidden,
        ascii,
    };

    // Build nodes for each path
    let mut root_nodes: Vec<Node> = Vec::new();
    for p_str in &paths {
        let path = Path::new(p_str);
        match build_node(path, &config, 0) {
            Ok(node) => root_nodes.push(node),
            Err(e) => {
                // permission denied etc handled inside build? But path existence already checked.
                eprintln!("{}", e);
                continue;
            }
        }
    }

    // If multiple paths, create collection node
    if root_nodes.len() > 1 {
        let total_size: u64 = root_nodes.iter().map(|n| n.size).sum();
        let collection_node = Node {
            name: "<collection>".to_string(),
            path: PathBuf::from("<collection>"),
            size: total_size,
            own_size: 0,
            is_dir: true,
            is_symlink: false,
            children: root_nodes,
            is_aggregated: false,
        };
        print_tree(&collection_node, &config);
    } else if root_nodes.len() == 1 {
        let node = &root_nodes[0];
        // If node is file, just print header [ name size ]
        if !node.is_dir {
            let size_str = if config.bytes {
                format!("{} B", node.size)
            } else {
                human_size(node.size)
            };
            println!("[ {} {} ]", node.name, size_str);
        } else {
            print_tree(node, &config);
        }
    }
}

fn build_node(path: &Path, config: &Config, current_depth: usize) -> Result<Node, String> {
    let metadata = fs::symlink_metadata(path).map_err(|e| format!("Couldn't read {} ({})", path.file_name().unwrap_or_else(|| std::ffi::OsStr::new("")).to_string_lossy(), e.kind()))?;
    let is_symlink = metadata.file_type().is_symlink();
    let is_dir = metadata.file_type().is_dir() && !is_symlink;
    let own_size = if config.usage {
        metadata.blocks() * 512
    } else {
        metadata.len()
    };

    let name = if path.file_name().is_some() {
        path.file_name().unwrap().to_string_lossy().to_string()
    } else {
        path.to_string_lossy().to_string()
    };

    if !is_dir {
        return Ok(Node {
            name,
            path: path.to_path_buf(),
            size: own_size,
            own_size,
            is_dir: false,
            is_symlink,
            children: Vec::new(),
            is_aggregated: false,
        });
    }

    // is dir
    let mut children: Vec<Node> = Vec::new();
    let mut total = own_size;

    // read dir entries
    let read_dir = match fs::read_dir(path) {
        Ok(rd) => rd,
        Err(e) => {
            eprintln!("Couldn't read {} ({})", name, e.kind());
            return Ok(Node {
                name,
                path: path.to_path_buf(),
                size: own_size,
                own_size,
                is_dir: true,
                is_symlink: false,
                children: Vec::new(),
                is_aggregated: false,
            });
        }
    };

    for entry_res in read_dir {
        let entry = match entry_res {
            Ok(en) => en,
            Err(e) => {
                // Could not read entry, print error?
                // We need entry name? Use unknown?
                eprintln!("Couldn't read {} ({})", "?", e.kind());
                continue;
            }
        };
        let file_name_os = entry.file_name();
        let file_name = file_name_os.to_string_lossy().to_string();

        if config.no_hidden && file_name.starts_with('.') {
            continue;
        }
        if config.exclude.iter().any(|pat| pat == &file_name) {
            continue;
        }

        let child_path = entry.path();
        // lstat child
        let child_meta = match fs::symlink_metadata(&child_path) {
            Ok(m) => m,
            Err(e) => {
                eprintln!("Couldn't read {} ({})", file_name, e.kind());
                continue;
            }
        };
        let child_is_symlink = child_meta.file_type().is_symlink();
        let child_is_dir = child_meta.file_type().is_dir() && !child_is_symlink;

        if config.files_only {
            if child_is_dir {
                // skip dirs entirely for files_only
                continue;
            } else {
                // file or symlink
                let child_own = if config.usage {
                    child_meta.blocks() * 512
                } else {
                    child_meta.len()
                };
                // For files_only, total for parent includes file sizes directly
                total += child_own;
                let node = Node {
                    name: file_name,
                    path: child_path,
                    size: child_own,
                    own_size: child_own,
                    is_dir: false,
                    is_symlink: child_is_symlink,
                    children: Vec::new(),
                    is_aggregated: false,
                };
                children.push(node);
            }
        } else {
            // normal mode
            if child_is_dir {
                // recursively build
                match build_node(&child_path, config, current_depth+1) {
                    Ok(child_node) => {
                        total += child_node.size;
                        children.push(child_node);
                    },
                    Err(e) => {
                        eprintln!("{}", e);
                        continue;
                    }
                }
            } else {
                let child_own = if config.usage {
                    child_meta.blocks() * 512
                } else {
                    child_meta.len()
                };
                total += child_own;
                let node = Node {
                    name: file_name,
                    path: child_path,
                    size: child_own,
                    own_size: child_own,
                    is_dir: false,
                    is_symlink: child_is_symlink,
                    children: Vec::new(),
                    is_aggregated: false,
                };
                children.push(node);
            }
        }
    }

    Ok(Node {
        name,
        path: path.to_path_buf(),
        size: total,
        own_size,
        is_dir: true,
        is_symlink: false,
        children,
        is_aggregated: false,
    })
}

fn print_tree(root: &Node, config: &Config) {
    let size_str = if config.bytes {
        format!("{} B", root.size)
    } else {
        human_size(root.size)
    };
    println!("[ {} {} ]", root.name, size_str);

    // For display, we need to sort children and apply aggregation and depth
    // Use recursive function
    let mut is_tty = io::stdout().is_terminal();
    let ls_colors = env::var("LS_COLORS").unwrap_or_default();
    let use_colors = !config.ascii && is_tty && !ls_colors.is_empty();
    let color_map = if use_colors {
        parse_ls_colors(&ls_colors)
    } else {
        HashMap::new()
    };

