    let mut big_children: Vec<Node> = Vec::new();
    let mut aggr_size: u64 = 0;

    for child in children {
        if config.aggr_threshold > 0 && child.size < config.aggr_threshold {
            aggr_size += child.size;
        } else {
            big_children.push(child.clone());
        }
    }

    // Sort big_children descending by size
    big_children.sort_by(|a,b| b.size.cmp(&a.size));

    if aggr_size > 0 {
        let aggr_node = Node {
            name: "<aggregated>".to_string(),
            path: PathBuf::from("<aggregated>"),
            size: aggr_size,
            own_size: aggr_size,
