fn parse_aggr(s: &str) -> Option<u64> {
    // s like "1K", "10M", "1024", "1B", "0", etc.
    // Valid: number + optional K/M/G (case-insensitive) OR number + B (bytes) OR plain number
    // Invalid if K/M/G followed by B, or other suffixes
    if s.is_empty() {
        return None;
    }
    // Find where digits end
    let mut num_end = 0;
    for (i, ch) in s.char_indices() {
        if ch.is_ascii_digit() {
            num_end = i + ch.len_utf8();
        } else {
            break;
        }
    }
    if num_end == 0 {
        return None;
    }
    let num_str = &s[..num_end];
    let suffix = &s[num_end..];
    let num: u64 = match num_str.parse() {
        Ok(v) => v,
        Err(_) => return None,
    };
    if suffix.is_empty() {
        return Some(num);
    }
    // suffix can be "B" or "K" or "M" or "G" case-insensitive, but not "KB" etc.
    // So suffix length 1, and must be B,K,M,G
    if suffix.len() == 1 {
        match suffix.to_ascii_uppercase().as_str() {
            "B" => Some(num),
            "K" => Some(num * 1024),
            "M" => Some(num * 1024 * 1024),
            "G" => Some(num * 1024 * 1024 * 1024),
            _ => None,
        }
    } else {
        None
    }
