fn display_children(nodes: &[Node], config: &Config, depth: usize, ancestor_lasts: Vec<bool>, parent_size: u64, parent_bar: usize, color_map: &HashMap<String,String>, use_colors: bool) {
    // nodes are already sorted and aggregated, with aggregated last
    // Compute max size among nodes for bar at this level if depth==1
    let max_size = nodes.iter().map(|n| n.size).max().unwrap_or(0);

    for (idx, node) in nodes.iter().enumerate() {
        let is_last = idx == nodes.len() -1;
        // prefix
        let mut prefix = String::new();
        for (a_idx, a_last) in ancestor_lasts.iter().enumerate() {
            if *a_last {
                prefix.push_str("   ");
            } else {
                prefix.push_str("│  ");
            }
        }
        let current_prefix = if is_last { "└─ " } else { "├─ " };
        let full_prefix = format!("{}{}", prefix, current_prefix);

        let left_width = 26;
        let name_field_width = if left_width > full_prefix.chars().count() { left_width - full_prefix.chars().count() } else { 1 };
        let max_name_len = if name_field_width > 1 { name_field_width -1 } else { 0 };
        let truncated_name = if node.name.chars().count() > max_name_len {
            node.name.chars().take(max_name_len).collect::<String>()
        } else {
            node.name.clone()
        };

        // Colorize name
        let colored_name = if use_colors && !node.is_aggregated {
            if let Some(color_code) = get_color_for_node(node, color_map) {
                format!("\x1b[{}m{}\x1b[0m", color_code, truncated_name)
            } else {
                truncated_name.clone()
            }
        } else {
            truncated_name.clone()
        };

        // For padding, we need to pad based on truncated_name char count, not colored version (since color codes don't count)
        let name_padded = format!("{:<width$}", truncated_name, width=max_name_len);
        // But if colors, we need to pad after color? Actually we should pad the colored name? The original pads after color? It had color codes around name, then spaces. So we should compute padding based on truncated_name len, then apply color only to name, then add spaces.
        let padding_len = if max_name_len > truncated_name.chars().count() { max_name_len - truncated_name.chars().count() } else { 0 };
        let colored_padded = if use_colors && !node.is_aggregated {
            if let Some(color_code) = get_color_for_node(node, color_map) {
                format!("\x1b[{}m{}\x1b[0m{:width$}", truncated_name, "", width=padding_len)
            } else {
                format!("{}{:width$}", truncated_name, "", width=padding_len)
            }
        } else {
            format!("{}{:width$}", truncated_name, "", width=padding_len)
        };
        let name_part = format!("{} ", colored_padded);

        let left = format!("{}{}", full_prefix, name_part);

        // percent
        let percent = if parent_size==0 { 0 } else { (node.size * 100 / parent_size) as usize };
        let size_str = if config.bytes {
            format!("{} B", node.size)
        } else {
            human_size(node.size)
        };
        let right = format!("{:4}%{:>14}", percent, size_str);

        // bar
        let bar_len = if depth==1 {
            // depth 1: proportional to max sibling
            if max_size==0 {
                0
            } else {
                // formula size*33//max -1 clamped
                let mut len = (node.size * 33 / max_size) as isize -1;
                if len <0 { len=0; }
                if len > BAR_WIDTH as isize { len=BAR_WIDTH as isize; }
