            // depth >=2 ascii: bar = parent_bar if parent_bar>0 else 0
            // For unicode, we might want proportional to parent_size?
            if config.ascii {
                parent_bar
            } else {
                // unicode: try to match observed: size*33//parent_size - (depth-1) ?
                // For depth>=2, using parent_size total
                if parent_size==0 {
                    0
                } else {
                    let mut len = (node.size * 33 / parent_size) as isize - (depth as isize -1);
                    if len <0 { len=0; }
                    if len > parent_bar as isize { len=parent_bar as isize; }
                    if len > BAR_WIDTH as isize { len=BAR_WIDTH as isize; }
                    len as usize
                }
            }
        };

        let bar_filled_char = if config.ascii { '#' } else { '█' };
        let bar_empty_char = if config.ascii {
            ' '
        } else {
            if depth==1 { ' ' } else { '░' }
        };
