        if p_idx < pat_chars.len() && (pat_chars[p_idx]==name_chars[n_idx] || pat_chars[p_idx]=='?') {
            p_idx+=1;
            n_idx+=1;
        } else if p_idx < pat_chars.len() && pat_chars[p_idx]=='*' {
            star_idx=Some(p_idx);
            match_idx=n_idx;
            p_idx+=1;
        } else if let Some(s_idx) = star_idx {
            p_idx=s_idx+1;
            match_idx+=1;
            n_idx=match_idx;
        } else {
            return false;
        }
    }
    while p_idx < pat_chars.len() && pat_chars[p_idx]=='*' {
        p_idx+=1;
    }
    p_idx==pat_chars.len()
}

fn get_color_for_node_ordered(node: &Node, ordered: &Vec<(String,String)>) -> Option<String> {
    if node.is_aggregated { return None; }
    // First check file type?
    // For simplicity, prioritize di and ln
    for (k,v) in ordered {
        if k=="di" && node.is_dir { return Some(v.clone()); }
        if k=="ln" && node.is_symlink { return Some(v.clone()); }
    }
    // Then check patterns
    for (k,v) in ordered {
        if k.contains('*') {
            if matches_glob(k, &node.name) {
                return Some(v.clone());
            }
        }
    }
    // Check fi? Not needed
    None
}

fn display_children(nodes: &[Node], config: &Config, depth: usize, ancestor_lasts: Vec<bool>, parent_size: u64, parent_bar: usize, _color_map: &HashMap<String,String>, use_colors: bool) {
    if nodes.is_empty() { return; }
    let max_size = nodes.iter().map(|n| n.size).max().unwrap_or(0);
    let ls_colors_ordered = if use_colors {
        parse_ls_colors_ordered(&env::var("LS_COLORS").unwrap_or_default())
    } else {
        Vec::new()
    };

    for (idx, node) in nodes.iter().enumerate() {
        let is_last = idx == nodes.len()-1;
        let mut prefix = String::new();
        for &a_last in &ancestor_lasts {
            if a_last {
                prefix.push_str("   ");
            } else {
                prefix.push_str("│  ");
            }
        }
        let cur = if is_last { "└─ " } else { "├─ " };
        let full_prefix = format!("{}{}", prefix, cur);

        let left_width = 26;
        let prefix_len = full_prefix.chars().count();
        let name_field_width = if left_width > prefix_len { left_width - prefix_len } else { 1 };
        let max_name_len = if name_field_width>1 { name_field_width-1 } else { 0 };

        let truncated = if node.name.chars().count() > max_name_len {
            node.name.chars().take(max_name_len).collect::<String>()
        } else {
            node.name.clone()
        };

        // color
        let colored_padded = if use_colors && !node.is_aggregated {
            if let Some(code) = get_color_for_node_ordered(node, &ls_colors_ordered) {
                let pad = max_name_len - truncated.chars().count();
                format!("\x1b[{}m{}\x1b[0m{:pad$}", truncated, "", pad=pad, width=pad)
            } else {
                format!("{:<width$}", truncated, width=max_name_len)
            }
        } else {
            format!("{:<width$}", truncated, width=max_name_len)
        };
        let name_part = format!("{} ", colored_padded);
        let left = format!("{}{}", full_prefix, name_part);

        let percent = if parent_size==0 { 0 } else { node.size *100 / parent_size };

        let size_str = if config.bytes {
            format!("{} B", node.size)
        } else {
            human_size(node.size)
        };
        let right = format!("{:4}%{:>14}", percent, size_str);

        let bar_len = if depth==1 {
            if max_size==0 { 0 } else {
                let mut l = (node.size * 33 / max_size) as isize -1;
                if l<0 { l=0; }
                if l> BAR_WIDTH as isize { l=BAR_WIDTH as isize; }
                l as usize
            }
        } else {
            if config.ascii {
                parent_bar
            } else {
                // unicode: size*33//parent_size - (depth-1) ?
                if parent_size==0 { 0 } else {
                    let mut l = (node.size * 33 / parent_size) as isize - (depth as isize -1);
                    if l<0 { l=0; }
                    if l> parent_bar as isize { l=parent_bar as isize; }
                    if l> BAR_WIDTH as isize { l=BAR_WIDTH as isize; }
                    l as usize
                }
            }
        };

        let (filled_char, empty_char) = if config.ascii {
            ('#',' ')
        } else {
            ('█',' ')
        };

        // For ascii depth>=2, we want bar full with parent_bar width, but our bar_len for ascii depth>=2 is parent_bar, which is full. So we need to produce bar with parent_bar hashes, not bar_len? Actually parent_bar is already the bar length of parent, which is 32 for full. For child depth>=2 ascii we set bar_len=parent_bar, which is full width of parent. So we produce bar with bar_len hashes.

        // For unicode depth>=2, bar_len is computed as above (partial), but we need shading for empty part: use '░' for empty?

        let empty_char = if config.ascii { ' ' } else {
            if depth==1 { ' ' } else { '░' }
        };

        let mut bar_content = String::new();
        for _ in 0..(BAR_WIDTH - bar_len) {
            bar_content.push(empty_char);
        }
        for _ in 0..bar_len {
            bar_content.push(filled_char);
        }

        // For deeper unicode with multiple shades, we have only one shade, but we try to approximate: For depth>=3, we could have more shades? For simplicity, use single shade.

        println!("{}│ {}{}│{}", left, bar_content, "", right);

        if node.is_dir && depth < config.depth {
            let child_nodes = prepare_children(&node.children, config);
            if !child_nodes.is_empty() {
                let mut new_anc = ancestor_lasts.clone();
                new_anc.push(is_last);
                // For children, parent_size = node.size, parent_bar = bar_len (for ascii) or BAR_WIDTH for depth1? Actually for next level, parent_bar is bar_len of current node.
                display_children(&child_nodes, config, depth+1, new_anc, node.size, bar_len, _color_map, use_colors);
            }
        }
    }
}
