use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{self, IsTerminal};
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};

const VERSION: &str = "0.2.18";
const DEFAULT_DEPTH_WITH_FLAG: usize = 1;
const DEFAULT_AGGR: u64 = 1024 * 1024; // 1M
const BAR_WIDTH: usize = 32;
const MAX_DEPTH_CAP: usize = 8;

#[derive(Debug)]
struct Config {
    depth: usize,
    aggr_threshold: u64,
    usage: bool,
    bytes: bool,
    files_only: bool,
    exclude: Vec<String>,
    no_hidden: bool,
