fn matches_glob(pat: &str, name: &str) -> bool {
    // simple glob with * only
    // Convert pattern to regex-like matching
    // We support * as wildcard for any chars
    // Use two-pointer algorithm
    let pat_chars: Vec<char> = pat.chars().collect();
    let name_chars: Vec<char> = name.chars().collect();
    let mut p_idx=0;
    let mut n_idx=0;
    let mut star_idx: Option<usize> = None;
    let mut match_idx=0;

    while n_idx < name_chars.len() {
        if p_idx < pat_chars.len() && (pat_chars[p_idx]==name_chars[n_idx] || pat_chars[p_idx]=='?') {
            p_idx+=1;
            n_idx+=1;
        } else if p_idx < pat_chars.len() && pat_chars[p_idx]=='*' {
            star_idx=Some(p_idx);
            match_idx=n_idx;
            p_idx+=1;
        } else if let Some(s_idx) = star_idx {
            p_idx=s_idx+1;
            match_idx+=1;
            n_idx=match_idx;
        } else {
            return false;
        }
    }
    while p_idx < pat_chars.len() && pat_chars[p_idx]=='*' {
        p_idx+=1;
    }
    p_idx==pat_chars.len()
}

