fn build_node(path: &Path, config: &Config) -> Result<Node, String> {
    let metadata = fs::symlink_metadata(path).map_err(|_| "".to_string())?;
    let is_symlink = metadata.file_type().is_symlink();
    let is_dir = metadata.file_type().is_dir() && !is_symlink;
    let own_size = if config.usage { metadata.blocks()*512 } else { metadata.len() };

    let name = if path.file_name().is_some() {
        path.file_name().unwrap().to_string_lossy().to_string()
    } else {
        if path.to_string_lossy() == "/" {
            "/".to_string()
        } else {
            path.to_string_lossy().to_string()
        }
    };

    if !is_dir {
        return Ok(Node {
            name,
            path: path.to_path_buf(),
            size: own_size,
            is_dir: false,
            is_symlink,
            children: Vec::new(),
            is_aggregated: false,
        });
    }

    let mut children: Vec<Node> = Vec::new();
    let mut total = own_size;

    let read_dir = match fs::read_dir(path) {
        Ok(rd)=>rd,
        Err(e)=>{
            eprintln!("Couldn't read {} ({})", name, e.kind());
            return Ok(Node {
                name,
                path: path.to_path_buf(),
                size: own_size,
                is_dir: true,
                is_symlink: false,
                children: Vec::new(),
                is_aggregated: false,
            });
        }
    };

    for entry_res in read_dir {
        let entry = match entry_res {
            Ok(en)=>en,
            Err(e)=>{
                eprintln!("Couldn't read {} ({})", "?", e.kind());
                continue;
            }
        };
        let file_name = entry.file_name().to_string_lossy().to_string();
        if config.no_hidden && file_name.starts_with('.') { continue; }
        if config.exclude.iter().any(|pat| pat==&file_name) { continue; }

        let child_path = entry.path();
        let child_meta = match fs::symlink_metadata(&child_path) {
            Ok(m)=>m,
            Err(e)=>{
                eprintln!("Couldn't read {} ({})", file_name, e.kind());
                continue;
            }
        };
        let child_is_symlink = child_meta.file_type().is_symlink();
        let child_is_dir = child_meta.file_type().is_dir() && !child_is_symlink;

        if config.files_only {
            if child_is_dir { continue; }
            let child_own = if config.usage { child_meta.blocks()*512 } else { child_meta.len() };
            total += child_own;
            children.push(Node {
                name: file_name,
                path: child_path,
                size: child_own,
                is_dir: false,
                is_symlink: child_is_symlink,
                children: Vec::new(),
                is_aggregated: false,
            });
        } else {
            if child_is_dir {
                if let Ok(child_node)=build_node(&child_path, config) {
                    total += child_node.size;
                    children.push(child_node);
                }
            } else {
                let child_own = if config.usage { child_meta.blocks()*512 } else { child_meta.len() };
                total += child_own;
                children.push(Node {
                    name: file_name,
                    path: child_path,
                    size: child_own,
                    is_dir: false,
                    is_symlink: child_is_symlink,
                    children: Vec::new(),
                    is_aggregated: false,
                });
            }
        }
    }

    Ok(Node {
        name,
        path: path.to_path_buf(),
        size: total,
        is_dir: true,
        is_symlink: false,
        children,
        is_aggregated: false,
    })
}

fn prepare_children(children: &[Node], config: &Config) -> Vec<Node> {
    let mut big: Vec<Node> = Vec::new();
    let mut aggr_size: u64 = 0;
    for child in children {
        if config.aggr_threshold>0 && child.size < config.aggr_threshold {
            aggr_size += child.size;
        } else {
            big.push(child.clone());
        }
    }
    big.sort_by(|a,b| b.size.cmp(&a.size));
    if aggr_size>0 {
        let aggr_node = Node {
            name: "<aggregated>".to_string(),
            path: PathBuf::from("<aggregated>"),
            size: aggr_size,
            is_dir: false,
            is_symlink: false,
            children: Vec::new(),
            is_aggregated: true,
        };
        big.push(aggr_node);
    }
    big
}

fn print_tree(root: &Node, config: &Config) {
    let size_str = if config.bytes { format!("{} B", root.size) } else { human_size(root.size) };
    println!("[ {} {} ]", root.name, size_str);
    if config.depth==0 { return; }

    let is_tty = io::stdout().is_terminal();
    let ls_colors = env::var("LS_COLORS").unwrap_or_default();
    let use_colors = !config.ascii && is_tty && !ls_colors.is_empty();

    let children = prepare_children(&root.children, config);
    display_children(&children, config, 1, Vec::new(), root.size, BAR_WIDTH, use_colors);
}

fn parse_ls_colors_ordered(s: &str) -> Vec<(String,String)> {
    let mut vec=Vec::new();
    for entry in s.split(':') {
        if entry.is_empty() { continue; }
        if let Some(eq)=entry.find('=') {
            vec.push((entry[..eq].to_string(), entry[eq+1..].to_string()));
        }
    }
    vec
}

fn matches_glob(pat: &str, name: &str) -> bool {
    let pat_chars: Vec<char> = pat.chars().collect();
    let name_chars: Vec<char> = name.chars().collect();
    let mut p_idx=0;
    let mut n_idx=0;
    let mut star_idx: Option<usize> = None;
    let mut match_idx=0;
    while n_idx < name_chars.len() {
        if p_idx < pat_chars.len() && (pat_chars[p_idx]==name_chars[n_idx] || pat_chars[p_idx]=='?') {
            p_idx+=1; n_idx+=1;
        } else if p_idx < pat_chars.len() && pat_chars[p_idx]=='*' {
            star_idx=Some(p_idx);
            match_idx=n_idx;
            p_idx+=1;
        } else if let Some(s_idx)=star_idx {
            p_idx=s_idx+1;
            match_idx+=1;
            n_idx=match_idx;
        } else {
            return false;
        }
    }
    while p_idx < pat_chars.len() && pat_chars[p_idx]=='*' { p_idx+=1; }
    p_idx==pat_chars.len()
}

fn get_color_for_node_ordered(node: &Node, ordered: &Vec<(String,String)>) -> Option<String> {
    if node.is_aggregated { return None; }
    for (k,v) in ordered {
        if k=="di" && node.is_dir { return Some(v.clone()); }
        if k=="ln" && node.is_symlink { return Some(v.clone()); }
    }
    for (k,v) in ordered {
        if k.contains('*') {
            if matches_glob(k, &node.name) {
                return Some(v.clone());
            }
        }
    }
    None
}

fn display_children(nodes: &[Node], config: &Config, depth: usize, ancestor_lasts: Vec<bool>, parent_size: u64, parent_bar: usize, use_colors: bool) {
    if nodes.is_empty() { return; }
    let max_size = nodes.iter().map(|n| n.size).max().unwrap_or(0);
    let ordered = if use_colors {
        parse_ls_colors_ordered(&env::var("LS_COLORS").unwrap_or_default())
    } else { Vec::new() };

    for (idx, node) in nodes.iter().enumerate() {
        let is_last = idx == nodes.len()-1;
        let mut prefix = String::new();
        for &a_last in &ancestor_lasts {
            if a_last { prefix.push_str("   "); } else { prefix.push_str("│  "); }
        }
        let cur = if is_last { "└─ " } else { "├─ " };
        let full_prefix = format!("{}{}", prefix, cur);

        let left_width = 26;
        let prefix_len = full_prefix.chars().count();
        let name_field_width = if left_width > prefix_len { left_width - prefix_len } else { 1 };
        let max_name_len = if name_field_width>1 { name_field_width-1 } else { 0 };

        let truncated = if node.name.chars().count() > max_name_len {
            node.name.chars().take(max_name_len).collect::<String>()
        } else {
            node.name.clone()
        };

        let colored_padded = if use_colors && !node.is_aggregated {
            if let Some(code) = get_color_for_node_ordered(node, &ordered) {
                let pad = max_name_len - truncated.chars().count();
                let mut s = String::new();
                s.push_str(&format!("\x1b[{}m", code));
                s.push_str(&truncated);
                s.push_str("\x1b[0m");
                for _ in 0..pad { s.push(' '); }
                s
            } else {
                format!("{:<width$}", truncated, width=max_name_len)
            }
        } else {
            format!("{:<width$}", truncated, width=max_name_len)
        };
        let name_part = format!("{} ", colored_padded);
        let left = format!("{}{}", full_prefix, name_part);

        let percent = if parent_size==0 { 0 } else { node.size *100 / parent_size };
        let size_str = if config.bytes { format!("{} B", node.size) } else { human_size(node.size) };
        let right = format!("{:4}%{:>14}", percent, size_str);

        let bar_len = if depth==1 {
            if max_size==0 { 0 } else {
                let mut l = (node.size * 33 / max_size) as isize -1;
                if l<0 { l=0; }
                if l> BAR_WIDTH as isize { l=BAR_WIDTH as isize; }
                l as usize
            }
        } else {
            if config.ascii {
                parent_bar
            } else {
                if parent_size==0 { 0 } else {
                    let mut l = (node.size * 33 / parent_size) as isize - (depth as isize -1);
                    if l<0 { l=0; }
                    if l> parent_bar as isize { l=parent_bar as isize; }
                    if l> BAR_WIDTH as isize { l=BAR_WIDTH as isize; }
                    l as usize
                }
            }
        };

        let (filled_char, empty_char) = if config.ascii {
            ('#',' ')
        } else {
            ('█',' ')
        };
        let empty_char = if config.ascii { ' ' } else {
            if depth==1 { ' ' } else { '░' }
        };

        let mut bar_content = String::new();
        for _ in 0..(BAR_WIDTH - bar_len) {
            bar_content.push(empty_char);
        }
        for _ in 0..bar_len {
            bar_content.push(filled_char);
        }

        println!("{}│ {}{}│{}", left, bar_content, "", right);

        if node.is_dir && depth < config.depth {
            let child_nodes = prepare_children(&node.children, config);
            if !child_nodes.is_empty() {
                let mut new_anc = ancestor_lasts.clone();
                new_anc.push(is_last);
                display_children(&child_nodes, config, depth+1, new_anc, node.size, bar_len, use_colors);
            }
        }
    }
}
