cd /workspace
cat > src/main.rs <<'RS'
use std::env;
use std::fs;
use std::io::{self, IsTerminal};
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};

const VERSION: &str = "0.2.18";
const DEFAULT_DEPTH_WITH_FLAG: usize = 1;
const DEFAULT_AGGR: u64 = 1024 * 1024;
const BAR_WIDTH: usize = 32;
const MAX_DEPTH_CAP: usize = 8;

#[derive(Debug)]
struct Config {
    depth: usize,
    aggr_threshold: u64,
    usage: bool,
    bytes: bool,
    files_only: bool,
    exclude: Vec<String>,
    no_hidden: bool,
    ascii: bool,
}

#[derive(Debug, Clone)]
struct Node {
    name: String,
    path: PathBuf,
    size: u64,
    is_dir: bool,
    is_symlink: bool,
    children: Vec<Node>,
    is_aggregated: bool,
}

fn human_size(size: u64) -> String {
    if size < 1024 {
        format!("{} B", size)
    } else if size < 1024 * 1024 {
        format!("{:.2} KiB", size as f64 / 1024.0)
    } else if size < 1024 * 1024 * 1024 {
        format!("{:.2} MiB", size as f64 / (1024.0 * 1024.0))
    } else if size < 1024u64 * 1024 * 1024 * 1024 {
        format!("{:.2} GiB", size as f64 / (1024.0 * 1024.0 * 1024.0))
    } else {
        format!("{:.2} TiB", size as f64 / (1024.0 * 1024.0 * 1024.0 * 1024.0))
    }
}

fn parse_depth(s: &str) -> Option<usize> {
    if s.is_empty() { return None; }
    s.parse::<usize>().ok()
}

fn parse_aggr(s: &str) -> Option<u64> {
    if s.is_empty() { return None; }
    let mut num_end = 0;
    for (i, ch) in s.char_indices() {
        if ch.is_ascii_digit() {
            num_end = i + ch.len_utf8();
        } else {
            break;
        }
    }
    if num_end == 0 { return None; }
    let num_str = &s[..num_end];
    let suffix = &s[num_end..];
    let num: u64 = num_str.parse().ok()?;
    if suffix.is_empty() {
        return Some(num);
    }
    if suffix.len() == 1 {
        match suffix.to_ascii_uppercase().as_str() {
            "B" => Some(num),
            "K" => Some(num * 1024),
            "M" => Some(num * 1024 * 1024),
            "G" => Some(num * 1024 * 1024 * 1024),
            _ => None,
        }
    } else {
        None
    }
}

fn print_help() {
    println!("Usage: ./executable [options] <path> [<path>..]");
    println!();
    println!("Options:");
    println!("    -d, --depth [DEPTH] show directories up to depth N (def 1)");
    println!("    -a, --aggr [N[KMG]] aggregate smaller than N B/KiB/MiB/GiB (def 1M)");
    println!("    -s, --summary       equivalent to -da, or -d1 -a1M");
    println!("    -u, --usage         report real disk usage instead of file size");
    println!("    -b, --bytes         print sizes in bytes");
    println!("    -f, --files-only    skip directories for a fast local overview");
    println!("    -x, --exclude NAME  exclude matching files or directories");
    println!("    -H, --no-hidden     exclude hidden files");
    println!("    -A, --ascii         ASCII characters only, no colors");
    println!("    -h, --help          show help");
    println!("    -v, --version       print version number");
}

fn print_version() {
    println!("dutree version {}", VERSION);
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut depth_opt: Option<usize> = None;
    let mut aggr_opt: Option<u64> = None;
    let mut usage = false;
    let mut bytes = false;
    let mut files_only = false;
    let mut exclude: Vec<String> = Vec::new();
    let mut no_hidden = false;
    let mut ascii = false;
    let mut summary = false;
    let mut help = false;
    let mut version = false;
    let mut paths: Vec<String> = Vec::new();

    let mut i = 1;
    while i < args.len() {
        let token = &args[i];
        if token == "--" {
            i+=1;
            while i < args.len() {
                paths.push(args[i].clone());
                i+=1;
            }
            break;
        }
        if token.starts_with("--") {
            if token == "--help" {
                help=true; i+=1; continue;
            } else if token == "--version" {
                version=true; i+=1; continue;
            } else if token == "--bytes" {
                bytes=true; i+=1; continue;
            } else if token == "--usage" {
                usage=true; i+=1; continue;
            } else if token == "--files-only" {
                files_only=true; i+=1; continue;
            } else if token == "--no-hidden" {
                no_hidden=true; i+=1; continue;
            } else if token == "--ascii" {
                ascii=true; i+=1; continue;
            } else if token == "--summary" {
                summary=true; i+=1; continue;
            } else if token.starts_with("--depth") {
                if token == "--depth" {
                    depth_opt=Some(DEFAULT_DEPTH_WITH_FLAG);
                    i+=1; continue;
                } else if token.starts_with("--depth=") {
                    let val_str = &token["--depth=".len()..];
                    if let Some(d)=parse_depth(val_str) {
                        depth_opt=Some(d);
                    } else {
                        depth_opt=Some(DEFAULT_DEPTH_WITH_FLAG);
                    }
                    i+=1; continue;
                } else {
                    eprintln!("Unrecognized option: '{}'", token.trim_start_matches("--").split('=').next().unwrap_or(""));
                    print_help();
                    std::process::exit(1);
                }
            } else if token == "--aggr" || token == "--aggregate" {
                aggr_opt=Some(DEFAULT_AGGR);
                i+=1; continue;
            } else if token.starts_with("--aggr=") || token.starts_with("--aggregate=") {
                let val_str = if token.starts_with("--aggr=") { &token["--aggr=".len()..] } else { &token["--aggregate=".len()..] };
                if let Some(sz)=parse_aggr(val_str) {
                    aggr_opt=Some(sz);
                } else {
                    eprintln!("invalid argument '{}'", val_str);
                    std::process::exit(1);
                }
                i+=1; continue;
            } else if token.starts_with("--exclude") {
                if token == "--exclude" {
                    i+=1;
                    if i>=args.len() {
                        print_help();
                        eprintln!("Argument to option 'exclude' missing");
                        std::process::exit(1);
                    }
                    exclude.push(args[i].clone());
                    i+=1; continue;
                } else if token.starts_with("--exclude=") {
                    let val = &token["--exclude=".len()..];
                    exclude.push(val.to_string());
                    i+=1; continue;
                } else {
                    eprintln!("Unrecognized option: '{}'", token.trim_start_matches("--").split('=').next().unwrap_or(""));
                    print_help();
                    std::process::exit(1);
                }
            } else {
                let name = token.trim_start_matches("--");
                let opt_name = name.split('=').next().unwrap_or(name);
                eprintln!("Unrecognized option: '{}'", opt_name);
                print_help();
                std::process::exit(1);
            }
        } else if token.starts_with("-") && token.len()>1 {
            let chars: Vec<char> = token[1..].chars().collect();
            let mut j=0;
            while j < chars.len() {
                let c = chars[j];
                match c {
                    'b' => { bytes=true; j+=1; },
                    'u' => { usage=true; j+=1; },
                    'f' => { files_only=true; j+=1; },
                    'H' => { no_hidden=true; j+=1; },
                    'A' => { ascii=true; j+=1; },
                    's' => { summary=true; j+=1; },
                    'h' => { help=true; j+=1; },
                    'v' => { version=true; j+=1; },
                    'd' => {
                        let remaining: String = chars[j+1..].iter().collect();
                        if !remaining.is_empty() {
                            if let Some(d)=parse_depth(&remaining) {
                                depth_opt=Some(d);
                            } else {
                                depth_opt=Some(DEFAULT_DEPTH_WITH_FLAG);
                            }
                            break;
                        } else {
                            if i+1 < args.len() && !args[i+1].starts_with("-") {
                                let next = args[i+1].clone();
                                if let Some(d)=parse_depth(&next) {
                                    depth_opt=Some(d);
                                } else {
                                    depth_opt=Some(DEFAULT_DEPTH_WITH_FLAG);
                                }
                                i+=1;
                            } else {
                                depth_opt=Some(DEFAULT_DEPTH_WITH_FLAG);
                            }
                            break;
                        }
                    },
                    'a' => {
                        let remaining: String = chars[j+1..].iter().collect();
                        if !remaining.is_empty() {
                            if let Some(sz)=parse_aggr(&remaining) {
                                aggr_opt=Some(sz);
                            } else {
                                eprintln!("invalid argument '{}'", remaining);
                                std::process::exit(1);
                            }
                            break;
                        } else {
                            if i+1 < args.len() && !args[i+1].starts_with("-") {
                                let next = args[i+1].clone();
                                if let Some(sz)=parse_aggr(&next) {
                                    aggr_opt=Some(sz);
                                    i+=1;
                                } else {
                                    eprintln!("invalid argument '{}'", next);
                                    std::process::exit(1);
                                }
                            } else {
                                aggr_opt=Some(DEFAULT_AGGR);
                            }
                            break;
                        }
                    },
                    'x' => {
                        let remaining: String = chars[j+1..].iter().collect();
                        if !remaining.is_empty() {
                            exclude.push(remaining);
                            break;
                        } else {
                            if i+1 >= args.len() {
                                print_help();
                                eprintln!("Argument to option 'x' missing");
                                std::process::exit(1);
                            }
                            let next = args[i+1].clone();
                            exclude.push(next);
                            i+=1;
                            break;
                        }
                    },
                    _ => {
                        eprintln!("Unrecognized option: '{}'", c);
                        print_help();
                        std::process::exit(1);
                    }
                }
            }
            i+=1;
        } else {
            paths.push(token.clone());
            i+=1;
        }
    }

    if help {
        print_help();
        std::process::exit(0);
    }
    if version {
        print_version();
        std::process::exit(0);
    }

    if summary {
        depth_opt=Some(1);
        aggr_opt=Some(DEFAULT_AGGR);
    }

    let depth = match depth_opt {
        Some(d) => std::cmp::min(d, MAX_DEPTH_CAP),
        None => MAX_DEPTH_CAP,
    };

    let aggr_threshold = aggr_opt.unwrap_or(0);

    if paths.is_empty() {
        paths.push(".".to_string());
    }

    for p in &paths {
        if fs::symlink_metadata(p).is_err() {
            eprintln!("path {} doesn't exist", p);
            std::process::exit(1);
        }
    }

    let config = Config {
        depth,
        aggr_threshold,
        usage,
        bytes,
        files_only,
        exclude,
        no_hidden,
        ascii,
    };

    let mut root_nodes: Vec<Node> = Vec::new();
    for p_str in &paths {
        let path = Path::new(p_str);
        if let Ok(node) = build_node(path, &config) {
            root_nodes.push(node);
        }
    }

    if root_nodes.len()>1 {
        let total: u64 = root_nodes.iter().map(|n| n.size).sum();
        let collection = Node {
            name: "<collection>".to_string(),
            path: PathBuf::from("<collection>"),
            size: total,
            is_dir: true,
            is_symlink: false,
            children: root_nodes,
            is_aggregated: false,
        };
        print_tree(&collection, &config);
    } else if let Some(node)=root_nodes.into_iter().next() {
        if !node.is_dir {
            let size_str = if config.bytes { format!("{} B", node.size) } else { human_size(node.size) };
            println!("[ {} {} ]", node.name, size_str);
        } else {
            print_tree(&node, &config);
        }
    }
}

fn build_node(path: &Path, config: &Config) -> Result<Node, String> {
    let metadata = fs::symlink_metadata(path).map_err(|_| "".to_string())?;
    let is_symlink = metadata.file_type().is_symlink();
    let is_dir = metadata.file_type().is_dir() && !is_symlink;
    let own_size = if config.usage { metadata.blocks()*512 } else { metadata.len() };

    let name = if path.file_name().is_some() {
        path.file_name().unwrap().to_string_lossy().to_string()
    } else {
        if path.to_string_lossy() == "/" {
            "/".to_string()
        } else {
            path.to_string_lossy().to_string()
        }
    };

    if !is_dir {
        return Ok(Node {
            name,
            path: path.to_path_buf(),
            size: own_size,
            is_dir: false,
            is_symlink,
            children: Vec::new(),
            is_aggregated: false,
        });
    }

    let mut children: Vec<Node> = Vec::new();
    let mut total = own_size;

    let read_dir = match fs::read_dir(path) {
        Ok(rd)=>rd,
        Err(e)=>{
            eprintln!("Couldn't read {} (PermissionDenied)", name);
            return Ok(Node {
                name,
                path: path.to_path_buf(),
                size: own_size,
                is_dir: true,
                is_symlink: false,
                children: Vec::new(),
                is_aggregated: false,
            });
        }
    };

    for entry_res in read_dir {
        let entry = match entry_res {
            Ok(en)=>en,
            Err(e)=>{
                eprintln!("Couldn't read {} (PermissionDenied)", "?");
                continue;
            }
        };
        let file_name = entry.file_name().to_string_lossy().to_string();
        if config.no_hidden && file_name.starts_with('.') { continue; }
        if config.exclude.iter().any(|pat| pat==&file_name) { continue; }

        let child_path = entry.path();
        let child_meta = match fs::symlink_metadata(&child_path) {
            Ok(m)=>m,
            Err(e)=>{
                eprintln!("Couldn't read {} (PermissionDenied)", file_name);
                continue;
            }
        };
        let child_is_symlink = child_meta.file_type().is_symlink();
        let child_is_dir = child_meta.file_type().is_dir() && !child_is_symlink;

        if config.files_only {
            if child_is_dir { continue; }
            let child_own = if config.usage { child_meta.blocks()*512 } else { child_meta.len() };
            total += child_own;
            children.push(Node {
                name: file_name,
                path: child_path,
                size: child_own,
                is_dir: false,
                is_symlink: child_is_symlink,
                children: Vec::new(),
                is_aggregated: false,
            });
        } else {
            if child_is_dir {
                if let Ok(child_node)=build_node(&child_path, config) {
                    total += child_node.size;
                    children.push(child_node);
                }
            } else {
                let child_own = if config.usage { child_meta.blocks()*512 } else { child_meta.len() };
                total += child_own;
                children.push(Node {
                    name: file_name,
                    path: child_path,
                    size: child_own,
                    is_dir: false,
                    is_symlink: child_is_symlink,
                    children: Vec::new(),
                    is_aggregated: false,
                });
            }
        }
    }

    Ok(Node {
        name,
        path: path.to_path_buf(),
        size: total,
        is_dir: true,
        is_symlink: false,
        children,
        is_aggregated: false,
    })
}

fn prepare_children(children: &[Node], config: &Config) -> Vec<Node> {
    let mut big: Vec<Node> = Vec::new();
    let mut aggr_size: u64 = 0;
    for child in children {
        if config.aggr_threshold>0 && child.size < config.aggr_threshold {
            aggr_size += child.size;
        } else {
            big.push(child.clone());
        }
    }
    big.sort_by(|a,b| b.size.cmp(&a.size));
    if aggr_size>0 {
        let aggr_node = Node {
            name: "<aggregated>".to_string(),
            path: PathBuf::from("<aggregated>"),
            size: aggr_size,
            is_dir: false,
            is_symlink: false,
            children: Vec::new(),
            is_aggregated: true,
        };
        big.push(aggr_node);
    }
    big
}

fn print_tree(root: &Node, config: &Config) {
    let size_str = if config.bytes { format!("{} B", root.size) } else { human_size(root.size) };
    println!("[ {} {} ]", root.name, size_str);
    if config.depth==0 { return; }

    let is_tty = io::stdout().is_terminal();
    let ls_colors = env::var("LS_COLORS").unwrap_or_default();
    let use_colors = !config.ascii && is_tty && !ls_colors.is_empty();

    let children = prepare_children(&root.children, config);
    display_children(&children, config, 1, Vec::new(), root.size, BAR_WIDTH, use_colors);
}

fn parse_ls_colors_ordered(s: &str) -> Vec<(String,String)> {
    let mut vec=Vec::new();
    for entry in s.split(':') {
        if entry.is_empty() { continue; }
        if let Some(eq)=entry.find('=') {
            vec.push((entry[..eq].to_string(), entry[eq+1..].to_string()));
        }
    }
    vec
}

fn matches_glob(pat: &str, name: &str) -> bool {
    let pat_chars: Vec<char> = pat.chars().collect();
    let name_chars: Vec<char> = name.chars().collect();
    let mut p_idx=0;
    let mut n_idx=0;
    let mut star_idx: Option<usize> = None;
    let mut match_idx=0;
    while n_idx < name_chars.len() {
        if p_idx < pat_chars.len() && (pat_chars[p_idx]==name_chars[n_idx] || pat_chars[p_idx]=='?') {
            p_idx+=1; n_idx+=1;
        } else if p_idx < pat_chars.len() && pat_chars[p_idx]=='*' {
            star_idx=Some(p_idx);
            match_idx=n_idx;
            p_idx+=1;
        } else if let Some(s_idx)=star_idx {
            p_idx=s_idx+1;
            match_idx+=1;
            n_idx=match_idx;
        } else {
            return false;
        }
    }
    while p_idx < pat_chars.len() && pat_chars[p_idx]=='*' { p_idx+=1; }
    p_idx==pat_chars.len()
}

fn get_color_for_node_ordered(node: &Node, ordered: &Vec<(String,String)>) -> Option<String> {
    if node.is_aggregated { return None; }
    for (k,v) in ordered {
        if k=="di" && node.is_dir { return Some(v.clone()); }
        if k=="ln" && node.is_symlink { return Some(v.clone()); }
    }
    for (k,v) in ordered {
        if k.contains('*') {
            if matches_glob(k, &node.name) {
                return Some(v.clone());
            }
        }
    }
    None
}

fn display_children(nodes: &[Node], config: &Config, depth: usize, ancestor_lasts: Vec<bool>, parent_size: u64, parent_bar: usize, use_colors: bool) {
    if nodes.is_empty() { return; }
    let max_size = nodes.iter().map(|n| n.size).max().unwrap_or(0);
    let ordered = if use_colors {
        parse_ls_colors_ordered(&env::var("LS_COLORS").unwrap_or_default())
    } else { Vec::new() };

    for (idx, node) in nodes.iter().enumerate() {
        let is_last = idx == nodes.len()-1;
        let mut prefix = String::new();
        for &a_last in &ancestor_lasts {
            if a_last { prefix.push_str("   "); } else { prefix.push_str("│  "); }
        }
        let cur = if is_last { "└─ " } else { "├─ " };
        let full_prefix = format!("{}{}", prefix, cur);

        let left_width = 26;
        let prefix_len = full_prefix.chars().count();
        let name_field_width = if left_width > prefix_len { left_width - prefix_len } else { 1 };
        let max_name_len = if name_field_width>1 { name_field_width-1 } else { 0 };

        let truncated = if node.name.chars().count() > max_name_len {
            node.name.chars().take(max_name_len).collect::<String>()
        } else {
            node.name.clone()
        };

        let colored_padded = if use_colors && !node.is_aggregated {
            if let Some(code) = get_color_for_node_ordered(node, &ordered) {
                let pad = max_name_len - truncated.chars().count();
                let mut s = String::new();
                s.push_str(&format!("\x1b[{}m", code));
                s.push_str(&truncated);
                s.push_str("\x1b[0m");
                for _ in 0..pad { s.push(' '); }
                s
            } else {
                format!("{:<width$}", truncated, width=max_name_len)
            }
        } else {
            format!("{:<width$}", truncated, width=max_name_len)
        };
        let name_part = format!("{} ", colored_padded);
        let left = format!("{}{}", full_prefix, name_part);

        let percent = if parent_size==0 { 0 } else { node.size *100 / parent_size };
        let size_str = if config.bytes { format!("{} B", node.size) } else { human_size(node.size) };
        let right = format!("{:4}%{:>14}", percent, size_str);

        let bar_len = if depth==1 {
            if max_size==0 { 0 } else {
                let mut l = (node.size * 33 / max_size) as isize -1;
                if l<0 { l=0; }
                if l> BAR_WIDTH as isize { l=BAR_WIDTH as isize; }
                l as usize
            }
        } else {
            if config.ascii {
                parent_bar
            } else {
                if parent_size==0 { 0 } else {
                    let mut l = (node.size * 33 / parent_size) as isize - (depth as isize -1);
                    if l<0 { l=0; }
                    if l> parent_bar as isize { l=parent_bar as isize; }
                    if l> BAR_WIDTH as isize { l=BAR_WIDTH as isize; }
                    l as usize
                }
            }
        };

        let filled_char = if config.ascii { '#' } else { '█' };
        let empty_char = if config.ascii { ' ' } else {
            if depth==1 { ' ' } else { '░' }
        };

        let mut bar_content = String::new();
        for _ in 0..(BAR_WIDTH - bar_len) {
            bar_content.push(empty_char);
        }
        for _ in 0..bar_len {
            bar_content.push(filled_char);
        }

        println!("{}│ {}{}│{}", left, bar_content, "", right);

        if node.is_dir && depth < config.depth {
            // For permission denied double print, try to read dir again
            if let Err(_) = fs::read_dir(&node.path) {
                // Only print second error if children were empty due to previous failure?
                // We'll check if node.children is empty but we are trying to display deeper
                // To match original double print, we print error again for unreadable dir
                // We need to get name
                eprintln!("Couldn't read {} (PermissionDenied)", node.name);
            }
            let child_nodes = prepare_children(&node.children, config);
            if !child_nodes.is_empty() {
                let mut new_anc = ancestor_lasts.clone();
                new_anc.push(is_last);
                display_children(&child_nodes, config, depth+1, new_anc, node.size, bar_len, use_colors);
            }
        }
    }
}
